(() => {
  const c31 = document.querySelector('#case31');
  const c32 = document.querySelector('#case32');
  const nav31 = document.querySelector('a[href="#case31"]');
  const nav32 = document.querySelector('a[href="#case32"]');
  const heroText = document.querySelector('.scroll-hint')?.textContent?.trim();
  return {
    case31: !!c31,
    case32: !!c32,
    nav31: !!nav31,
    nav32: !!nav32,
    heroText,
    totalCases: document.querySelectorAll('[id^="case"]').length
  };
})()

