(() => {
  const ids = [28,29,30,31,32].map(n => `case${n}`);
  const found = ids.map(id => ({ id, exists: !!document.getElementById(id) }));
  const total = document.querySelectorAll('[id^="case"]').length;
  const heroText = document.querySelector('.scroll-hint')?.textContent?.trim();
  const navItems = document.querySelectorAll('.nav-item');
  const navCount = navItems.length;
  return { found, total, heroText, navCount };
})()

